var EXTRA=[{dot:"gray",j:"Canadian Journal of Surgery",h:"Complicanze di protesi d'anca e ginocchio in un ospedale privato canadese, dati prospettici",v:"Serie prospettica di un solo centro privato ad alto volume, con percorso di recupero accelerato: gli autori riportano tassi di complicanze bassi; è descrittiva, senza gruppo di confronto.",pmid:'42810741',doi:'10.1503/cjs.018625',temi:["protesi di ginocchio","complicanze","qualità dell'assistenza"]},{dot:"gray",j:"The Journal of Knee Surgery",h:"Fratture del piatto tibiale negli anziani: fragilità e mortalità, qualità della riduzione e fallimento",v:"Coorte retrospettiva di un solo centro, piccola: la fragilità predice la morte, la complessità della frattura e la riduzione non anatomica predicono il fallimento; l'idea della protesi primaria con carico immediato va provata in studi prospettici.",pmid:'42810380',doi:'10.1055/a-2968-6152',temi:["frattura del piatto tibiale","fragilità","protesi primaria"]},{dot:"gray",j:"Clinical Biomechanics",h:"Nell'artrosi del ginocchio la velocità del cammino dipende anche dal movimento dell'anca",v:"Studio trasversale su pazienti in attesa di intervento, con cattura del movimento da smartphone (OpenCap): l'ampiezza di movimento dell'anca e la forza degli estensori si associano alla velocità del cammino; sono associazioni, non cause.",pmid:'42809907',doi:'10.1016/j.clinbiomech.2026.106979',temi:["analisi del cammino","artrosi","cattura del movimento"]},{dot:"gray",j:"Anesthesiology",h:"Oppioidi a rilascio prolungato dopo protesi: piccolo aumento di uso persistente e di riammissioni",v:"Analisi amministrativa di popolazione con ponderazione per propensione: le associazioni sono piccole e coerenti, ma non dimostrano una causa e non riguardano la tecnica chirurgica.",pmid:'42808787',doi:'10.1097/ALN.0000000000006400',temi:["protesi di ginocchio","analgesia","oppioidi"]},{dot:"gray",j:"Canadian Journal of Surgery",h:"ChatGPT e informazioni ai pazienti sulle protesi: accuratezza confrontata con chirurghi e specializzandi",v:"Studio su cinque domande frequenti, valutate da un solo chirurgo indipendente: le risposte del modello risultano più accurate e complete di quelle umane; campione di domande minimo e nessun esito clinico.",pmid:'42810739',doi:'10.1503/cjs.018325',temi:["intelligenza artificiale","informazione al paziente","protesi"]},{dot:"gray",j:"JBJS Case Connect",h:"Sindrome della fabella dopo meniscectomia laterale artroscopica, con imaging seriato",v:"Caso singolo: dolore posterolaterale persistente dopo meniscectomia, con fabella ingrandita e conflitto con il condilo; la fabellectomia artroscopica ha risolto i sintomi. Un caso non stabilisce una relazione causale.",pmid:'42809648',doi:'10.2106/JBJS.CC.26.00149',temi:["menisco","meniscectomia","dolore posterolaterale"]},{dot:"gray",j:"JBJS Case Connect",h:"Menisco discoide mediale completo, con una variante anatomica mai descritta prima",v:"Caso singolo di una giovane donna: la risonanza e l'artroscopia mostrano la mancanza dell'inserzione ossea del corno anteriore, legato al menisco laterale da un legamento; gli autori insistono sulla risonanza multiplanare.",pmid:'42809646',doi:'10.2106/JBJS.CC.26.00273',temi:["menisco discoide","variante anatomica","risonanza"]},{dot:"gray",j:"European Journal of Applied Physiology",h:"Biomarcatori della cartilagine dopo camminata e ciclismo in giovani sani",v:"Studio su un piccolo gruppo di uomini sani: la camminata modifica di più alcuni marcatori circolanti; sono marcatori indiretti, non misure della cartilagine, in soggetti senza malattia.",pmid:'42806071',doi:'10.1007/s00421-026-06453-w',temi:["cartilagine","biomarcatori","esercizio"]},{dot:"gray",j:"Journal of Pain Research",h:"Agopuntura con moxa e tuina nell'artrosi: meta-analisi sui marcatori infiammatori",v:"Meta-analisi di studi cinesi: riduzione di marcatori infiammatori, ma la certezza delle prove è da molto bassa a bassa, e i marcatori non sono esiti clinici.",pmid:'42802793',doi:'10.2147/JPR.S636990',temi:["artrosi","agopuntura","infiammazione"]},{dot:"gray",j:"Zhongguo Gu Shang",h:"Elettroagopuntura prima dell'intervento per il dolore dopo protesi: studio randomizzato cinese",v:"Studio randomizzato di un solo centro, con follow-up di sette giorni: l'intervento prima dell'operazione riduce il dolore acuto più di quello dopo; durata troppo breve per dire altro sull'esito.",pmid:'42803050',doi:'10.12200/j.issn.1003-0034.20250200',temi:["dolore postoperatorio","protesi di ginocchio","medicina cinese"]},{dot:"gray",j:"Journal of Robotic Surgery",h:"L'interesse del pubblico per la chirurgia ortopedica robotica cresce di anno in anno",v:"Analisi delle ricerche su Google dal 2014: l'interesse per il ginocchio robotico cresce molto; misura l'attenzione del pubblico, non la domanda né l'efficacia.",pmid:'42804031',doi:'10.1007/s11701-026-04005-0',temi:["chirurgia robotica","protesi di ginocchio","informazione al paziente"]},{dot:"gray",j:"Journal of Robotic Surgery",h:"Mappa bibliometrica della protesi monocompartimentale assistita da robot",v:"Analisi bibliometrica della letteratura: la ricerca si sposta dalla precisione tecnica ai risultati a lungo termine e alla sopravvivenza dell'impianto; non riporta esiti clinici propri.",pmid:'42803861',doi:'10.1007/s11701-026-03937-x',temi:["protesi monocompartimentale","robot","bibliometria"]}];
var SCOPERTE=[{t:"Nanomotori di esosomi che si fanno strada nella cartilagine sfruttando lo stress ossidativo dell'artrosi",v:"Un gruppo del West China Hospital (Sichuan, Cina) costruisce vettori esosomiali che usano le molecole ossidanti dell'articolazione artrosica come propulsione, per far penetrare un farmaco in un tessuto denso e senza vasi. Vale la deviazione perché affronta il vero collo di bottiglia della terapia intra-articolare, cioè arrivare dove serve; è uno studio sul ratto, molto lontano dalla clinica.",pmid:'42805962',doi:'10.1038/s41467-026-76949-8',temi:["bioingegneria","cartilagine","artrosi"]},{t:"Nanostrutture di DNA e cerio contro artrosi, cartilagine e osso sottostante insieme",v:"Un gruppo del Dipartimento di materiali polimerici dell'Università Tongji (Cina) assembla oligonucleotidi e cristalli di cerio in particelle che, iniettate nell'articolazione, eliminano radicali dell'ossigeno, orientano i macrofagi e frenano gli osteoclasti. Vale la deviazione perché prova a trattare insieme cartilagine, infiammazione e osso subcondrale, invece di un solo bersaglio; modello animale, nessun dato umano.",pmid:'42809755',doi:'10.1021/acsami.6c11655',temi:["nanomedicina","osso subcondrale","artrosi"]},{t:"La stampa 3D dei tessuti: dove i supporti osteocondrali incontrano i limiti di produzione",v:"Una rassegna dell'Università di Friburgo (Germania) sui colli di bottiglia della produzione additiva per l'ingegneria tissutale, con le unità osteocondrali come banco di prova, e su che cosa serve per la clinica: validazione funzionale, standardizzazione, regolamentazione. Vale la deviazione perché mostra che cosa ferma la produzione su misura di cartilagine e osso; è una rassegna, non contiene dati clinici.",pmid:'42807625',doi:'10.3389/fbioe.2026.1929172',temi:["stampa 3D","ingegneria tissutale","osteocondrale"]}];
var SOC={"1": {"video": "Quando la radice posteriore del menisco interno si stacca, il chirurgo può riattaccarla in due modi: con una sutura all'interno dell'articolazione, detta all-inside, oppure passando i fili attraverso un tunnel nella tibia. Una revisione di dodici studi, pubblicata su Arthroscopy, li ha confrontati: quattro studi hanno messo le due tecniche una contro l'altra, su 153 pazienti seguiti in media per quasi due anni. Entrambe hanno migliorato i punteggi riferiti dai pazienti. Guardando i dettagli, nessuna delle due prevale in modo costante. La guarigione completa varia dal 65 al 68 per cento circa con la sutura interna, e dal 21 all'86 per cento con il tunnel nella tibia: un intervallo così ampio significa che gli studi sono molto diversi fra loro, e che non si può dire quale tecnica guarisca di più. Anche i test di resistenza in laboratorio hanno dato risultati contraddittori. Il punto più importante è un altro. In nessuno dei due casi il menisco torna in modo costante nella sua posizione originale: resta spostato verso l'esterno. Gli autori suggeriscono che serva un gesto in più, la centralizzazione, ma non l'hanno verificato. Va detto che gli studi sono in gran parte non randomizzati: per questo la scelta della tecnica va decisa caso per caso.", "linkedin": "Revisione sistematica (Vosoughi, Menbari Oskouie, Entezari et al., Arthroscopy, settembre 2026), 12 studi (8 clinici, 4 biomeccanici): riparazione della radice posteriore del menisco mediale, all-inside contro pull-out transtibiale. Quattro studi clinici con confronto diretto, 153 pazienti, follow-up medio 23,7 mesi.\n\nEntrambe le tecniche migliorano in modo significativo i punteggi riferiti dal paziente. Variazione del Lysholm: 20,8-38,2 (all-inside) contro 11,0-45,8 (pull-out). Guarigione completa: 64,7-67,8% contro 21,5-85,7%. Biomeccanica: carichi di rottura più alti con l'all-inside in 2 studi su 4, risultati nel complesso contraddittori. Nessuna delle due corregge in modo costante l'estrusione (da -2,2 a -0,6 mm contro da -1,9 a +0,1).\n\nLimiti: eterogeneità sostanziale, prove in prevalenza non randomizzate, intervalli di confidenza non riportati nell'abstract, intervalli di guarigione troppo larghi per un verdetto. Gli autori indicano la centralizzazione come aggiunta possibile: la revisione non l'ha verificata. La scelta della tecnica resta individuale.", "instagram": "🦵 Radice del menisco: due modi di riattaccarla, risultati simili. Una revisione di 12 studi, con 4 confronti diretti su 153 pazienti, non trova una tecnica costantemente superiore.\n\nIn nessuno dei due casi il menisco torna in modo costante nella sua posizione: resta spostato verso l'esterno.\n\nGli studi sono molto diversi fra loro e in gran parte non randomizzati: la scelta si fa caso per caso.", "pazienti": "Il menisco è un cuscinetto dentro il ginocchio, tenuto in posizione da un'ancora all'osso chiamata radice. Quando la radice si stacca, il chirurgo può riattaccarla in due modi: con una sutura all'interno dell'articolazione oppure passando i fili attraverso un tunnel nella tibia. Una revisione di dodici studi pubblicata su Arthroscopy ha confrontato le due tecniche, e in quattro studi le due strade sono state messe direttamente a confronto su 153 persone. Con entrambe i punteggi riferiti dai pazienti migliorano, e nessuna delle due si è dimostrata costantemente superiore all'altra. Dopo l'operazione, però, il menisco resta un po' spostato verso l'esterno con entrambe le tecniche: è un limite che i ricercatori stanno ancora cercando di superare. Gli studi sono molto diversi fra loro e in gran parte non hanno assegnato i pazienti a sorte, quindi non si può dire che un metodo sia migliore dell'altro. La scelta della tecnica dipende dal singolo caso e dal chirurgo che segue il paziente."}};
var SOCV={"1": {"video": {"chir": ["Radice posteriore del menisco mediale: la sutura all-inside è paragonabile al pull-out transtibiale? Una revisione sistematica su Arthroscopy ha incluso dodici studi, otto clinici e quattro biomeccanici, fino ad agosto 2025. Quattro studi clinici, per un totale di 153 pazienti con follow-up medio di 23,7 mesi, hanno confrontato direttamente le due tecniche. Entrambe migliorano in modo significativo i punteggi riferiti dal paziente, e nessuna risulta costantemente superiore all'altra.", "Ecco i numeri, con la loro ampiezza. La variazione del Lysholm va da 20,8 a 38,2 punti con l'all-inside e da 11,0 a 45,8 con il pull-out. La guarigione completa va dal 64,7 al 67,8 per cento con l'all-inside e dal 21,5 all'85,7 per cento con il pull-out. In due studi biomeccanici l'all-inside ha carichi di rottura più alti, ma nel complesso i risultati sono contraddittori. Intervalli di confidenza non sono riportati nell'abstract.", "Il punto che resta è l'estrusione: nessuna delle due tecniche la corregge in modo costante, ed è forse il limite più importante della riparazione oggi. Gli autori indicano la centralizzazione come possibile aggiunta, ma la revisione non l'ha verificata. Limiti: studi in prevalenza non randomizzati, eterogeneità sostanziale, solo quattro confronti diretti. La scelta della tecnica va individualizzata, non fondata su una presunta superiorità."], "misto": ["Quando la radice posteriore del menisco interno si stacca, il chirurgo può riattaccarla in due modi: con una sutura all'interno dell'articolazione, detta all-inside, oppure passando i fili attraverso un tunnel nella tibia. Una revisione di dodici studi, pubblicata su Arthroscopy, li ha confrontati: quattro studi hanno messo le due tecniche una contro l'altra, su 153 pazienti seguiti in media per quasi due anni. Entrambe hanno migliorato i punteggi riferiti dai pazienti.", "Guardando i dettagli, nessuna delle due prevale in modo costante. La guarigione completa varia dal 65 al 68 per cento circa con la sutura interna, e dal 21 all'86 per cento con il tunnel nella tibia: un intervallo così ampio significa che gli studi sono molto diversi fra loro, e che non si può dire quale tecnica guarisca di più. Anche i test di resistenza in laboratorio hanno dato risultati contraddittori.", "Il punto più importante è un altro. In nessuno dei due casi il menisco torna in modo costante nella sua posizione originale: resta spostato verso l'esterno. Gli autori suggeriscono che serva un gesto in più, la centralizzazione, ma non l'hanno verificato. Va detto che gli studi sono in gran parte non randomizzati: per questo la scelta della tecnica va decisa caso per caso."], "pazienti": ["Il menisco è un cuscinetto dentro il ginocchio, tenuto in posizione da un'ancora all'osso chiamata radice. Quando la radice si stacca, il chirurgo può riattaccarla in due modi diversi. Una revisione di dodici studi ha confrontato le due tecniche, e in quattro di questi studi i due modi sono stati messi direttamente a confronto su 153 persone.", "Il risultato è che entrambi i modi hanno portato a un miglioramento dei punteggi riferiti dai pazienti, e che nessuno dei due si è dimostrato costantemente superiore. Gli studi però sono molto diversi fra loro, e in gran parte non hanno assegnato i pazienti a sorte: per questo non si può dire che un metodo sia migliore dell'altro.", "C'è poi un limite che riguarda entrambe le tecniche: dopo l'operazione il menisco non torna in modo costante nella sua posizione originale, ma resta un po' spostato verso l'esterno. I ricercatori sono ancora al lavoro per capire come correggerlo. Se hai una lesione di questo tipo, la scelta della tecnica dipende dal tuo caso e dal chirurgo che ti segue."]}, "linkedin": {"chir": ["Revisione sistematica (Vosoughi, Menbari Oskouie, Entezari et al., Arthroscopy, settembre 2026), 12 studi (8 clinici, 4 biomeccanici): riparazione della radice posteriore del menisco mediale, all-inside contro pull-out transtibiale. Quattro studi clinici con confronto diretto, 153 pazienti, follow-up medio 23,7 mesi.", "Entrambe le tecniche migliorano in modo significativo i punteggi riferiti dal paziente. Variazione del Lysholm: 20,8-38,2 (all-inside) contro 11,0-45,8 (pull-out). Guarigione completa: 64,7-67,8% contro 21,5-85,7%. Biomeccanica: carichi di rottura più alti con l'all-inside in 2 studi su 4, risultati nel complesso contraddittori. Nessuna delle due corregge in modo costante l'estrusione (da -2,2 a -0,6 mm contro da -1,9 a +0,1).", "Limiti: eterogeneità sostanziale, prove in prevalenza non randomizzate, intervalli di confidenza non riportati nell'abstract, intervalli di guarigione troppo larghi per un verdetto. Gli autori indicano la centralizzazione come aggiunta possibile: la revisione non l'ha verificata. La scelta della tecnica resta individuale."], "misto": ["Revisione sistematica su Arthroscopy (settembre 2026): 12 studi sulla riparazione della radice posteriore del menisco mediale, sutura all-inside a confronto con il pull-out transtibiale. Quattro studi le confrontano direttamente su 153 pazienti, seguiti in media 23,7 mesi.", "Entrambe le tecniche migliorano i punteggi riferiti dai pazienti e nessuna prevale in modo costante. La guarigione completa varia dal 65% al 68% circa con l'all-inside e dal 21% all'86% con il pull-out: un intervallo così ampio riflette studi molto diversi fra loro. In nessuno dei due casi il menisco torna in modo costante nella sua posizione: l'estrusione resta.", "Il limite: gli studi sono in gran parte non randomizzati e molto eterogenei. Gli autori suggeriscono la centralizzazione come possibile aggiunta, ma non l'hanno verificata; la scelta della tecnica va decisa caso per caso."], "pazienti": ["Menisco: quando si stacca la radice, cioè l'ancora che lo tiene all'osso, si può riattaccarla in due modi. Una revisione su Arthroscopy ha confrontato 12 studi, fra cui 4 che mettono le due tecniche a confronto diretto su 153 persone.", "Entrambi i modi migliorano i punteggi riferiti dai pazienti e nessuno risulta costantemente superiore all'altro. Dopo l'operazione il menisco resta un po' spostato verso l'esterno con entrambe le tecniche.", "Gli studi sono diversi fra loro e in gran parte non confrontano i gruppi a sorte: non si può dire che un metodo sia migliore. La scelta dipende dal caso e dal chirurgo."]}, "instagram": {"chir": ["🦵 Radice del menisco mediale: all-inside o pull-out transtibiale? Revisione sistematica, 12 studi, 153 pazienti nei 4 confronti diretti: entrambe migliorano i punteggi, nessuna prevale in modo costante.", "Guarigione completa: 64,7-67,8% (all-inside) contro 21,5-85,7% (pull-out). Nessuna delle due corregge in modo costante l'estrusione.", "Limiti: studi in prevalenza non randomizzati, molto eterogenei, intervalli di confidenza non riportati nell'abstract."], "misto": ["🦵 Radice del menisco: due modi di riattaccarla, risultati simili. Una revisione di 12 studi, con 4 confronti diretti su 153 pazienti, non trova una tecnica costantemente superiore.", "In nessuno dei due casi il menisco torna in modo costante nella sua posizione: resta spostato verso l'esterno.", "Gli studi sono molto diversi fra loro e in gran parte non randomizzati: la scelta si fa caso per caso."], "pazienti": ["🦵 Menisco staccato dalla radice: due modi per riattaccarlo danno risultati simili. Una revisione di 12 studi ha confrontato le due tecniche.", "Con entrambe i punteggi migliorano, ma il menisco resta un po' spostato verso l'esterno.", "Gli studi sono diversi fra loro: non si può dire che un metodo sia migliore dell'altro."]}, "reel": {"chir": ["[RADICE MENISCALE] Revisione sistematica, 12 studi: all-inside contro pull-out transtibiale, 153 pazienti nei confronti diretti.", "[IL RISULTATO] Punteggi migliorati con entrambe, nessuna prevale; nessuna corregge in modo costante l'estrusione.", "[IL LIMITE] Studi in prevalenza non randomizzati e molto eterogenei."], "misto": ["[MENISCO] Due modi di riattaccare la radice: sutura interna o tunnel nella tibia. Una revisione di 12 studi li ha confrontati.", "[IL RISULTATO] Punteggi migliorati con entrambi, nessuno prevale; il menisco resta un po' spostato in fuori.", "[IL LIMITE] Studi molto diversi fra loro, in gran parte non randomizzati."], "pazienti": ["[MENISCO] Se si stacca la radice, ci sono due modi per riattaccarla. Una revisione di 12 studi li ha confrontati.", "[IL RISULTATO] Con entrambi i punteggi migliorano; il menisco resta un po' spostato.", "[IL LIMITE] Gli studi sono diversi fra loro: nessun metodo risulta superiore."]}}};
var TAGS={"1": {"linkedin": "#Ortopedia #Menisco #ChirurgiaDelGinocchio", "instagram": "#ortopedia #menisco #radicemeniscale #ginocchio #chirurgiadelginocchio #artroscopia #medicinasportiva #sportsmedicine #ortopediaticino", "kw": "menisco radice, riparazione menisco, sutura menisco ginocchio"}};
var NLB={"1": {"prof": ["Radice mediale: all-inside e pull-out transtibiale simili, ma l'estrusione non si corregge", "Una revisione sistematica di 12 studi (4 confronti diretti, 153 pazienti, follow-up medio 23,7 mesi) non trova una tecnica costantemente superiore fra sutura all-inside e pull-out transtibiale nella radice posteriore del menisco mediale: entrambe migliorano i punteggi riferiti dal paziente, la guarigione completa va da 64,7% a 67,8% con l'all-inside e da 21,5% a 85,7% con il pull-out, e nessuna corregge in modo costante l'estrusione.", "Nota critica: eterogeneità sostanziale, prove in prevalenza non randomizzate, intervalli di confidenza non riportati nell'abstract e intervalli di guarigione troppo larghi per un verdetto; la centralizzazione suggerita dagli autori non è stata verificata."], "mix": ["Menisco: due modi di suturare la radice, risultati simili, posizione non corretta", "Quando la radice posteriore del menisco interno si stacca, si può riattaccarla con una sutura all'interno dell'articolazione oppure passando il filo attraverso un tunnel nella tibia. Una revisione di 12 studi, di cui 4 confrontano direttamente le due strade su 153 pazienti, trova un miglioramento con entrambe e nessuna differenza costante; in nessuno dei due casi il menisco torna del tutto nella posizione originale, cioè resta spostato verso l'esterno.", "Nota sul limite: gli studi sono in gran parte non randomizzati e molto diversi fra loro, e i valori di guarigione variano moltissimo da uno studio all'altro, quindi non si può dire che una tecnica sia migliore."], "paz": ["Menisco: due modi per riattaccare la radice danno risultati simili", "Il menisco è un cuscinetto dentro il ginocchio, tenuto in posizione da un'ancora all'osso chiamata radice. Quando la radice si stacca, i chirurghi possono fissarla in due modi. Una revisione di 12 studi ha visto che i due modi portano a miglioramenti simili nei punteggi riferiti dai pazienti, ma in nessuno dei due il menisco torna del tutto nella sua posizione.", "Gli studi sono diversi fra loro e in gran parte non confrontano i gruppi a sorte: per questo non si può dire che un modo sia superiore all'altro."], "kw": "menisco radice, riparazione menisco, sutura menisco ginocchio"}, "2": {"prof": ["Tutore di scarico nell'artrosi tibiofemorale: consenso Delphi di 29 esperti", "Un consenso Delphi modificato di 29 specialisti della preservazione articolare su 5 continenti, con 3 round di votazione, raggiunge il consenso su tutte le 42 affermazioni finali: il tutore riduce la pressione di contatto del comparto interessato, va considerato in un percorso multimodale, può servire come test di selezione prima di un'osteotomia e come supporto postoperatorio, con una prova diagnostica di almeno 6 settimane e un periodo terapeutico di 6 mesi.", "Nota critica: consenso di esperti, livello V, non un dato di efficacia; panel composto da specialisti della preservazione articolare, percentuali di accordo per singola affermazione non riportate nell'abstract."], "mix": ["Artrosi del ginocchio: un gruppo di esperti concorda su come usare il tutore di scarico", "Ventinove specialisti di cinque continenti hanno votato in tre round una serie di raccomandazioni sul tutore di scarico, cioè il tutore che sposta il carico da un lato all'altro del ginocchio. Concordano che alleggerisce il compartimento colpito, che si può provare per almeno sei settimane per capire se aiuta, e che può servire anche prima di un intervento di correzione dell'asse della gamba.", "Nota sul limite: è l'opinione concorde di un gruppo di esperti, non la misura dei risultati su pazienti; non sostituisce un intervento quando è indicato."], "paz": ["Ginocchio artrosico: cosa raccomandano gli esperti sul tutore di scarico", "Il tutore di scarico è un supporto che sposta parte del peso da un lato del ginocchio all'altro. Ventinove specialisti hanno concordato che può aiutare alcune persone con artrosi su un lato solo del ginocchio, provandolo per almeno sei settimane prima di decidere se continuare.", "Si tratta dell'opinione condivisa di un gruppo di esperti: non è la prova che il tutore funzioni per tutti e non sostituisce un intervento quando serve."], "kw": "tutore ginocchio artrosi, artrosi ginocchio trattamento, osteotomia ginocchio"}, "3": {"prof": ["MPFL: sling dell'adduttore o tunnel femorale anatomico, Kujala mediano 91,0 contro 94,0", "Una coorte retrospettiva multicentrica su 84 ginocchia (19 con sling dell'adduttore, 65 con tunnel femorale anatomico) dopo ricostruzione del MPFL non trova una differenza chiara: Kujala mediano 91,0 contro 94,0 (differenza -3,0; IC 95% da -8,5 a 2,5), nuova lussazione 0/18 contro 2/62, instabilità residua riferita 6/18 contro 13/62.", "Nota critica: follow-up diverso (35,6 contro 55,6 mesi), TTO concomitante in 66,2% contro 31,6% e solo 18 ginocchi con sling: gli intervalli non escludono differenze rilevanti in nessuna direzione."], "mix": ["Rotula che si lussa: due modi di fissare il legamento ricostruito danno punteggi simili", "Quando la rotula si lussa più volte, si può ricostruire il legamento che la trattiene. Uno studio su 84 ginocchia ha confrontato due modi di fissare il nuovo legamento sul femore, con un passaggio attorno a un tendine oppure con un tunnel osseo. I punteggi di funzione dopo l'intervento sono risultati alti e simili, e le nuove lussazioni sono state poche in entrambi i gruppi.", "Nota sul limite: i due gruppi erano diversi per tempo di controllo e per interventi associati, e nel gruppo con il passaggio attorno al tendine i ginocchi erano solo 18; per questo non si può escludere una differenza."], "paz": ["Lussazione della rotula: due tecniche di ricostruzione con punteggi simili", "Dopo una lussazione ripetuta della rotula si può ricostruire il legamento che la tiene in sede. In uno studio su 84 ginocchia sono stati confrontati due modi di fissarlo all'osso della coscia. In entrambi i casi i punteggi di funzione dopo l'intervento erano alti e le nuove lussazioni poche.", "Lo studio è retrospettivo e i gruppi erano di dimensioni e durata di controllo diverse: non permette di dire che un modo sia superiore all'altro."], "kw": "lussazione rotula, legamento femororotuleo mediale, instabilità rotula"}, "4": {"prof": ["Protesi totale: allineamento cinematico con più soddisfazione e meno sintomi residui a 1 anno", "Una coorte retrospettiva su 622 protesi totali con lo stesso impianto (315 con allineamento cinematico, 307 meccanico) riporta a 1 anno soddisfazione complessiva del 94,0% contro 81,1% (p<0,001) e Forgotten Joint Score di 91,7 contro 82,7 (p<0,001), con dolore residuo 11,7% contro 24,1%.", "Nota critica: studio retrospettivo non randomizzato, esiti riferiti dal paziente, intervalli di confidenza non riportati nell'abstract e assegnazione dell'allineamento non descritta."], "mix": ["Protesi di ginocchio: con l'allineamento cinematico più pazienti soddisfatti a un anno", "In 622 pazienti con protesi di ginocchio dello stesso tipo, l'impianto posizionato secondo l'anatomia individuale del paziente, chiamato allineamento cinematico, ha dato a un anno più soddisfazione e meno dolore e scatti residui rispetto all'allineamento meccanico standard, con una soddisfazione del 94,0% contro 81,1%.", "Nota sul limite: i pazienti non sono stati assegnati a sorte e le risposte sono quelle riferite dai pazienti, quindi la differenza è un'associazione e non prova che sia il tipo di allineamento a causarla."], "paz": ["Protesi di ginocchio: come si posiziona l'impianto può cambiare la sensazione a un anno", "In 622 persone operate di protesi totale di ginocchio, chi aveva l'impianto posizionato secondo la forma del proprio ginocchio ha riferito più spesso di sentirlo normale e di avere meno dolore rispetto a chi aveva l'allineamento standard.", "I pazienti non sono stati scelti a sorte per i due metodi e i dati riguardano un solo anno: lo studio segnala una differenza, senza dimostrarne la causa."], "kw": "protesi ginocchio, dolore dopo protesi, allineamento protesi"}, "5": {"prof": ["Dopo la protesi, il controllo sistematico a distanza scopre di rado un problema", "In una coorte retrospettiva monocentrica di 74 revisioni per complicanze comparse oltre 12 mesi dopo protesi d'anca, di ginocchio o monocompartimentale, 52 (70,3%) sono emerse fuori dai controlli programmati e solo 2 (2,7%) erano asintomatiche; il tempo mediano alla diagnosi è stato 39,0 contro 53,5 mesi (p=0,45).", "Nota critica: lo studio include solo pazienti già rivisti, senza i pazienti seguiti e rimasti senza complicanze: non può misurare la sensibilità del controllo; p=0,45 su 22 contro 52 casi non prova equivalenza."], "mix": ["Protesi d'anca e di ginocchio: i controlli programmati a distanza trovano pochi problemi", "In uno studio su 74 pazienti sottoposti a un nuovo intervento per un problema comparso oltre un anno dopo la protesi, la maggior parte dei problemi (52) è stata scoperta quando il paziente ha avuto sintomi e ha chiesto una visita, non durante i controlli programmati. Solo due problemi non davano alcun sintomo.", "Nota sul limite: lo studio guarda solo chi ha poi avuto bisogno di un nuovo intervento, non tutti i pazienti controllati, quindi non dice quanti problemi i controlli riescano a prevenire."], "paz": ["Protesi: i controlli programmati a distanza scoprono pochi problemi nascosti", "In uno studio su 74 persone che hanno avuto bisogno di un secondo intervento alla protesi, quasi tutte avevano già dei disturbi quando il problema è stato scoperto. Solo in due casi non c'era alcun sintomo.", "Lo studio non dice come sarebbero andati i pazienti senza controlli programmati, e i dati sono di un solo ospedale."], "kw": "controlli dopo protesi, protesi ginocchio complicanze, follow-up protesi"}, "6": {"prof": ["Cartilagine: una rassegna sulle terapie cellulari indica che una soluzione unica non esiste", "Una rassegna narrativa 1970-2026 sulle terapie cellulari e di ingegneria tissutale per la cartilagine, valutate in vivo, ripercorre l'impianto di condrociti autologhi, le cellule mesenchimali, le staminali pluripotenti e i supporti a gradiente, e conclude che una soluzione unica è irrealistica e che identificare i pazienti che rispondono a un trattamento è la chiave.", "Nota critica: rassegna narrativa senza criteri di selezione descritti nell'abstract e senza esiti quantificati; non consente di confrontare le tecniche."], "mix": ["Cartilagine del ginocchio: i tentativi di ripararla, e perché non c'è una risposta unica", "Una rassegna della letteratura dal 1970 a oggi riassume le tecniche che cercano di ricostruire la cartilagine con cellule del paziente o con supporti costruiti in laboratorio. Gli autori concludono che non esiste una soluzione adatta a tutti e che il compito è capire quali pazienti rispondano meglio a quale trattamento.", "Nota sul limite: è una rassegna descrittiva, senza numeri sui risultati, quindi non stabilisce quale tecnica sia più efficace."], "paz": ["Cartilagine: perché ripararla è ancora difficile e non c'è una tecnica per tutti", "La cartilagine del ginocchio si ripara con difficoltà perché non ha vasi che la nutrano. Una rassegna di cinquant'anni di ricerche descrive diversi metodi con cellule e materiali, e conclude che non esiste ancora un metodo adatto a tutti: serve capire per quale persona funzioni quale tecnica.", "La rassegna descrive il campo senza riportare numeri sui risultati: non dice quale tecnica dia più benefici."], "kw": "cartilagine ginocchio riparazione, lesione cartilagine, condrociti"}, "7": {"prof": ["Artrosi: il C-score del femore su TC in carico si associa alla progressione a 2 anni", "Nella Multicenter Osteoarthritis Study, su 649 ginocchia, un indice di forma del femore distale su TC in carico, il C-score, si associa al peggioramento dello spazio articolare mediale (OR 1,43; IC 95% 1,07-1,92; p=0,01) e al peggioramento clinicamente importante del dolore a 2 anni (OR 1,27; IC 95% 1,00-1,62; p=0,047).", "Nota critica: solo 70 ginocchia con progressione, associazione con il dolore al limite (IC 95% 1,00-1,62), nessuna soglia decisionale né validazione su altre coorti nell'abstract."], "mix": ["Artrosi del ginocchio: una misura della forma del femore che aiuta a prevedere il peggioramento", "In 649 ginocchia seguite per due anni, una misura della forma dell'osso della coscia ricavata dalla tomografia in carico, chiamata C-score, si è associata al restringimento dello spazio articolare interno e al peggioramento del dolore. L'associazione è moderata, con un aumento delle probabilità di circa 1,4 volte per lo spazio articolare e di circa 1,3 volte per il dolore.", "Nota sul limite: le progressioni erano solo 70 e l'associazione con il dolore è al limite della significatività; è una misura di ricerca, non uno strumento per decidere una terapia."], "paz": ["Artrosi: la forma dell'osso può dare indizi sul peggioramento futuro", "In uno studio su 649 ginocchia seguite per due anni, i ricercatori hanno misurato la forma dell'osso della coscia con una tomografia eseguita in piedi. Chi aveva un valore più alto di questa misura, chiamata C-score, aveva un po' più spesso un peggioramento dell'artrosi e del dolore.", "L'associazione è moderata e la misura è ancora in fase di ricerca: non serve oggi a prevedere che cosa accadrà al singolo paziente."], "kw": "artrosi ginocchio progressione, TAC ginocchio in carico, dolore artrosi"}, "8": {"prof": ["Protesi totale: nomogramma per il recupero scarso a 3 mesi, AUC 0,861 nel test interno", "Un modello sviluppato su 360 protesi totali primarie combina età, BMI, WOMAC funzione preoperatorio, grado di Outerbridge e due marcatori del liquido sinoviale (IL-6, COMP) per stimare il rischio di recupero scarso a 3 mesi: AUC 0,861 (IC 95% 0,782-0,934) nel test interno e 0,842 dopo correzione per ottimismo.", "Nota critica: validazione solo interna, prelievo di liquido sinoviale non routinario, soglia di WOMAC per il recupero scarso non riportata nell'abstract; gli autori stessi richiedono una validazione prospettica esterna."], "mix": ["Protesi di ginocchio: un modello prova a prevedere chi recupera lentamente nei primi tre mesi", "Su 360 pazienti operati di protesi totale, un modello matematico combina età, peso, punteggio funzionale prima dell'intervento, stato della cartilagine e due sostanze misurate nel liquido dell'articolazione per stimare chi avrà un recupero scarso a tre mesi. Nei dati di prova interni il modello distingue i due gruppi con buona accuratezza, con un indice di 0,86 su 1.", "Nota sul limite: il modello è stato provato solo sugli stessi dati con cui è nato, e non si sa se funzioni in altri ospedali; per ora non è uno strumento per la pratica."], "paz": ["Protesi di ginocchio: uno studio cerca di prevedere il recupero dei primi mesi", "Ricercatori hanno costruito un modello matematico su 360 persone operate di protesi di ginocchio, per stimare prima dell'intervento chi avrebbe avuto un recupero più lento nei primi tre mesi. Il modello usa dati come età, peso, punteggio funzionale e alcune sostanze misurate nel liquido dell'articolazione.", "Il modello è stato provato solo su dati dello stesso ospedale: prima di usarlo per i pazienti va confermato in altri centri."], "kw": "recupero dopo protesi ginocchio, protesi totale ginocchio, riabilitazione protesi"}};
var ARTICLES=[{n:1,mono:"m-gray",dot:"orange",sec:"res",j:"Arthroscopy",h:"Radice mediale: all-inside e pull-out simili, nessuno dei due corregge l'estrusione",v:"Revisione sistematica di 12 studi (4 confronti diretti, 153 pazienti, follow-up medio 23,7 mesi): entrambe le suture migliorano i punteggi, guarigione completa 64,7-67,8% con l'all-inside contro 21,5-85,7% con il pull-out, estrusione non corretta.",ax:"Vosoughi, Menbari Oskouie, Entezari, Torkamanzadeh, Taghva Nakhjiri",date:"set 2026",meta:"revisione sistematica di studi clinici e biomeccanici, 12 studi (4 confronti diretti, 153 pazienti) · [III]",pmid:'42809375',doi:'10.1002/arj.70626',journal:"Arthroscopy",authors:"Vosoughi F, Menbari Oskouie I, Entezari A, Torkamanzadeh P, Taghva Nakhjiri M",design:"Revisione sistematica su PubMed, Embase, Scopus e Web of Science fino ad agosto 2025, con sintesi qualitativa (punteggi funzionali, guarigione del menisco, estrusione, eterogeneità e rischio di bias). Inclusi gli studi clinici sulla riparazione all-inside della lesione della radice posteriore del menisco mediale e tutti quelli che confrontano all-inside e pull-out transtibiale, sul piano clinico o biomeccanico.",pop:"12 studi (8 clinici, 4 biomeccanici). Quattro studi clinici, per un totale di 153 pazienti con follow-up medio di 23,7 mesi, confrontano direttamente le due tecniche.",results:"Entrambe le riparazioni migliorano in modo significativo i punteggi riferiti dal paziente; in uno studio la quota di pazienti che raggiunge la differenza minima clinicamente importante è più alta con l'all-inside. Variazione del Lysholm da 20,8 a 38,2 punti con l'all-inside e da 11,0 a 45,8 con il pull-out. Guarigione completa da 64,7% a 67,8% con l'all-inside e da 21,5% a 85,7% con il pull-out. Estrusione mediale postoperatoria, come riportata nell'abstract: da -2,2 a -0,6 mm con l'all-inside contro da -1,9 a +0,1 con il pull-out. Biomeccanica: in 2 dei 4 studi l'all-inside ha carichi di rottura più alti, ma nel complesso i risultati sono contraddittori. Sono riportati intervalli di valori, non dimensioni dell'effetto: intervalli di confidenza e p non riportati nell'abstract.",concl:"Gli autori concludono che la riparazione all-inside, come il pull-out convenzionale, è sicura ed efficace per funzione, differenza minima clinicamente importante e guarigione; che nessuna delle due tecniche corregge in modo costante la posizione del menisco, perché la correzione dell'estrusione non è raggiunta; e che, data l'eterogeneità e la natura in prevalenza non randomizzata delle prove, la scelta va individualizzata e non basata su una presunta differenza di efficacia.",limits:"Eterogeneità sostanziale e prove in prevalenza non randomizzate (dichiarato dagli autori) · solo 4 confronti diretti e 153 pazienti: intervalli larghissimi, per esempio guarigione completa dal 21,5% all'85,7% con il pull-out · l'abstract non riporta intervalli di confidenza né i numeri assoluti dei singoli studi · articolo non open access: testo completo non aperto, numeri e limiti da abstract.",perte:"Il pull-out transtibiale è la tua tecnica, ed è uno dei due bracci: qui non emerge né un vantaggio né uno svantaggio rispetto all'all-inside su punteggi e guarigione. Il punto che pesa è l'altro: nessuna delle due corregge l'estrusione, ed è la variabile su cui T2b insiste. Gli autori indicano la centralizzazione come aggiunta possibile, ma la revisione non ne verifica l'efficacia: T2b resta aperta."},{n:2,mono:"m-gray",dot:"green",sec:"res",j:"Arthroscopy",h:"Tutore di scarico nell'artrosi: 29 esperti lo sostengono come test prima dell'osteotomia",v:"Consenso Delphi di 29 esperti su 5 continenti, 3 round: tutte le 42 affermazioni finali raggiungono il consenso; prova diagnostica di almeno 6 settimane, terapeutica di 6 mesi. Consenso di esperti, non dati di efficacia.",ax:"Super, Tollefson, Murray, Chahla, Geeslin, Johnson, Stevenson, LaPrade",date:"set 2026",meta:"consenso Delphi modificato di esperti, 29 esperti su 5 continenti, 3 round · [V]",pmid:'42809374',doi:'10.1002/arj.70579',journal:"Arthroscopy",authors:"Super JT, Tollefson LV, Murray IR, Chahla J, Geeslin AG, Johnson DL, Stevenson CM, LaPrade RF, più un autore collettivo (nome non riportato nei metadati)",design:"Processo Delphi modificato, secondo le indicazioni metodologiche di Arthroscopy per i consensus: riunione di revisione delle prove con discussioni in gruppi, 57 affermazioni iniziali votate in forma anonima in 3 round su scala di Likert a 5 punti. Soglie di consenso: almeno 70% di accordo e meno del 20% di disaccordo nei round 1 e 2; almeno 75% e meno del 10% nel round 3.",pop:"29 specialisti della preservazione articolare del ginocchio su 5 continenti; tutti e 29 hanno completato tutti e 3 i round (risposta 100%).",results:"Tutte le 42 affermazioni del round 3 hanno raggiunto il consenso. Forte accordo sul fatto che il tutore di scarico riduce la pressione di contatto del comparto interessato e vada considerato in un percorso multimodale per l'artrosi tibiofemorale. Il consenso sostiene il tutore nell'artrosi monocompartimentale sintomatica, in particolare con allineamento correggibile all'esame clinico; come test di selezione prima di un'osteotomia; come sintomatico in attesa dell'intervento; come supporto postoperatorio nei pazienti sintomatici con malallineamento omolaterale. Concordata una prova diagnostica di almeno 6 settimane e un periodo terapeutico di 6 mesi. Priorità di ricerca: protocolli standardizzati e studi randomizzati di buona qualità. Dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori concludono che il tutore di scarico non deve sostituire le opzioni chirurgiche definitive quando indicate, ma può essere un supporto o un'alternativa in pazienti selezionati, in particolare con malattia monocompartimentale e malallineamento correggibile.",limits:"Consenso di esperti, livello V: dice che cosa un gruppo ritiene ragionevole, non che il tutore funzioni · panel di 29 specialisti della preservazione articolare: una possibile predisposizione favorevole al trattamento conservativo e alla chirurgia correttiva non è valutabile dall'abstract · l'abstract non riporta le percentuali di accordo affermazione per affermazione · articolo non open access: testo completo non aperto.",perte:"Tocca la tua chirurgia correttiva: il tutore come prova prima di un'osteotomia è un'indicazione già concordata da un panel internazionale e si può usare per selezionare i pazienti. È la seconda consensus della stessa serie e dello stesso gruppo dopo quella sul tutore nelle lesioni cartilaginee focali del 26 settembre; con Robert LaPrade fra gli autori. Non dice nulla su innesto, LET o radice meniscale."},{n:3,mono:"m-gray",dot:"green",sec:"res",j:"Journal of ISAKOS",h:"MPFL: fissazione femorale con sling dell'adduttore o tunnel anatomico, Kujala simile",v:"84 ginocchia in 78 pazienti (19 sling, 65 tunnel): Kujala mediano 91,0 contro 94,0, differenza -3,0 (IC 95% da -8,5 a 2,5); nuova lussazione 0/18 contro 2/62; instabilità residua 6/18 contro 13/62.",ax:"Guiloff Krauss, Arteaga Correa, Isla Villanueva, Prado García, Figueroa Berríos, Vaisman Burucker, Calvo Rodriguez, Figueroa Poblete",date:"set 2026",meta:"coorte retrospettiva comparativa multicentrica, 84 ginocchia (19 sling, 65 tunnel anatomico) · [III]",pmid:'42810622',doi:'10.1016/j.jisako.2026.101225',journal:"Journal of ISAKOS",authors:"Guiloff Krauss R, Arteaga Correa JT, Isla Villanueva J, Prado García JL, Figueroa Berríos F, Vaisman Burucker A, Calvo Rodriguez R, Figueroa Poblete D",design:"Coorte retrospettiva comparativa multicentrica su ricostruzione del MPFL per instabilità rotulea laterale recidivante (2017-2024): fissazione femorale con sling dell'adduttore (AS) contro tunnel femorale anatomico (AFT). Esclusi interventi omolaterali precedenti e, in concomitanza, trocleoplastica, osteotomia femorale correttiva o osteotomia tibiale diversa dalla trasposizione della tuberosità tibiale (TTO). Esito primario: Kujala finale; regressione esplorativa aggiustata per età, sesso, follow-up e TTO, con errori standard robusti per i ginocchi bilaterali.",pop:"84 ginocchia in 78 pazienti scheletricamente maturi (19 AS, 65 AFT); esiti disponibili per 80 ginocchia (18 AS, 62 AFT). Follow-up mediano 35,6 mesi con AS contro 55,6 con AFT (p<0,001).",results:"Kujala mediano 91,0 (AS) contro 94,0 (AFT): differenza -3,0 (IC 95% da -8,5 a 2,5; p=0,456); nel modello aggiustato -5,31 (IC 95% da -12,61 a 1,99; p=0,151). Nuova lussazione 0/18 contro 2/62 (p=1,000). Instabilità residua 6/18 (33,3%) contro 13/62 (21,0%): differenza di rischio 12,4% (IC 95% da -8,3% a 36,7%; p=0,347). TTO concomitante più frequente con AFT (66,2% contro 31,6%; p=0,009). Nessun intervento successivo dopo AS, quattro dopo AFT (due nello stesso paziente per la stessa complicanza).",concl:"Gli autori concludono che entrambe le fissazioni danno punteggi funzionali alti e basse rilussazioni, senza una differenza chiara sul Kujala; l'instabilità residua riferita è stata più frequente con l'AS, ma la stima è imprecisa e si basa su una valutazione retrospettiva non standardizzata. Servono studi prospettici con indicazioni e valutazione dell'instabilità standardizzate.",limits:"I due gruppi non sono sovrapponibili: follow-up di 35,6 contro 55,6 mesi e TTO concomitante in 66,2% contro 31,6% · solo 18 ginocchi con sling: intervalli larghi, il lavoro non esclude né un vantaggio né uno svantaggio del sling · instabilità residua valutata in modo retrospettivo e non standardizzato (dichiarato) · articolo non open access: testo completo non aperto.",perte:"Tu ricostruisci il MPFL con ancore FiberTak in tecnica onlay: nessuno dei due bracci coincide con la tua fissazione femorale. Il lavoro dice che sling e tunnel anatomico non mostrano una differenza chiara sul Kujala, ma non offre dati sull'onlay con ancore."},{n:4,mono:"m-gray",dot:"gray",sec:"res",j:"Knee Surgery, Sports Traumatology, Arthroscopy",h:"Protesi di ginocchio: allineamento cinematico con meno sintomi residui a un anno",v:"Coorte retrospettiva di 622 protesi (315 cinematiche, 307 meccaniche): soddisfazione 94,0% contro 81,1% (p<0,001), Forgotten Joint Score 91,7 contro 82,7 (p<0,001); non randomizzato, intervalli di confidenza non riportati.",ax:"Campi, Giurazza, Franceschetti, Hirschmann, Tanzilli, Paciotti, Zampogna, Pepe, Gregori, Longo, Papalia",date:"set 2026",meta:"coorte retrospettiva comparativa, 622 protesi totali (315 contro 307), follow-up minimo 1 anno · [III]",pmid:'42809367',doi:'10.1002/ksa.70621',journal:"Knee Surgery, Sports Traumatology, Arthroscopy",authors:"Campi S, Giurazza G, Franceschetti E, Hirschmann MT, Tanzilli A, Paciotti M, Zampogna B, Pepe M, Gregori P, Longo UG, Papalia R",design:"Coorte retrospettiva su protesi totale primaria per artrosi avanzata (2022-2024), follow-up minimo di 1 anno: allineamento cinematico non restrittivo (KA) contro allineamento meccanico (MA), con lo stesso disegno di impianto e protocolli perioperatori standardizzati. Esiti: soddisfazione, prestazione funzionale, sintomi residui e percezione dell'articolazione (Forgotten Joint Score, FJS; Joint Awareness Score, JAS); test t e chi quadrato.",pop:"622 pazienti operati di protesi totale primaria: 315 KA e 307 MA.",results:"Soddisfazione complessiva 94,0% con KA contro 81,1% con MA (p<0,001); nelle attività quotidiane 92,7% contro 83,1% (p<0,001); nel sollievo dal dolore 90,2% contro 82,1% (p=0,005). Sintomi residui: dolore 11,7% contro 24,1% (p<0,001), scatti 7,3% contro 17,9% (p<0,001); ginocchio «normale» 89,8% contro 79,2% (p<0,001). FJS 91,7 contro 82,7 e JAS 92,3 contro 83,5 (entrambi p<0,001). Nessuna differenza significativa nella salita delle scale, nel gonfiore e nella rigidità. Intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori concludono che l'allineamento cinematico non restrittivo si associa a meno sintomi residui, funzione migliore e maggiore soddisfazione rispetto al meccanico a 1 anno, e lo propongono come strategia per ridurre il «ginocchio infelice» dopo protesi.",limits:"Studio retrospettivo non randomizzato: l'abstract non dice come è stato scelto l'allineamento per ciascun paziente né se i due gruppi differissero per periodo o per caratteristiche di partenza · esiti riferiti dal paziente, a 1 anno · solo p, senza intervalli di confidenza sulle differenze, e con molti confronti (rischio di risultati per caso) · articolo non open access: testo completo non aperto.",perte:"Riguarda la protesi totale, dove operi con VELYS. L'abstract non dice con quale tecnica (manuale, navigata o robotica) fosse ottenuto l'allineamento né con quale impianto (uno solo, lo stesso nei due gruppi): il risultato non è attribuibile alla tua piattaforma. È un'associazione, non una prova causale."},{n:5,mono:"m-gray",dot:"gray",sec:"res",j:"Canadian Journal of Surgery",h:"Dopo la protesi, il controllo sistematico a distanza trova pochi problemi",v:"Coorte retrospettiva monocentrica di 74 revisioni per complicanze oltre i 12 mesi: 52 (70,3%) emerse fuori dai controlli programmati, solo 2 (2,7%) asintomatiche; tempo alla diagnosi 39,0 contro 53,5 mesi (p=0,45).",ax:"Arsenault, Riel, Tardif, Bédard, Deshaies",date:"set 2026",meta:"coorte retrospettiva monocentrica, 74 revisioni (protesi d'anca, di ginocchio, monocompartimentale) · [IV]",pmid:'42810740',doi:'10.1503/cjs.021725',journal:"Canadian journal of surgery",authors:"Arsenault A, Riel N, Tardif A, Bédard S, Deshaies A",design:"Coorte retrospettiva monocentrica (2003-2020) di pazienti sottoposti a revisione per complicanze comparse oltre 12 mesi dopo protesi primaria totale d'anca, totale di ginocchio o monocompartimentale di ginocchio. Ogni complicanza è classificata secondo se è stata scoperta in un controllo sistematico (programmato) o non sistematico (non programmato o guidato dai sintomi). Esito primario: numero di complicanze per gruppo; secondari: tempo alla diagnosi, complicanze sintomatiche contro asintomatiche.",pop:"633 revisioni nel periodo, 74 con i requisiti di inclusione: 52 scoperte nel controllo non sistematico e 22 nel sistematico.",results:"52 su 74 (70,3%) complicanze scoperte fuori dai controlli programmati. Dal 2003 solo 2 (2,7%) complicanze si sono presentate come asintomatiche. Tempo mediano alla diagnosi di 39,0 mesi con controllo sistematico contro 53,5 con non sistematico (p=0,45). Intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori concludono che il controllo sistematico a lungo termine ha un'efficacia limitata nel rilevare complicanze che richiedono revisione, e che servono strategie di follow-up alternative che migliorino la qualità dell'assistenza e riducano il carico dei controlli attuali.",limits:"Include solo pazienti già sottoposti a revisione: mancano quelli seguiti senza problemi, quindi lo studio non può misurare quante complicanze il controllo previene né la sua sensibilità · un solo centro, retrospettivo, con anca e ginocchio insieme nell'abstract · p=0,45 su 22 contro 52 casi: non è prova di equivalenza dei tempi · articolo non open access: testo completo non aperto.",perte:"Non tocca una tua tecnica ma il follow-up dopo protesi monocompartimentale e totale: suggerisce che i controlli programmati a distanza in assenza di sintomi scoprono di rado un problema. L'abstract non separa il ginocchio dall'anca, quindi non dà cifre specifiche per le tue protesi."},{n:6,mono:"m-gray",dot:"gray",sec:"res",j:"Osteoarthritis and Cartilage",h:"Riparazione della cartilagine: una rassegna dice che nessuna soluzione vale per tutti",v:"Rassegna narrativa delle terapie cellulari e di ingegneria tissutale valutate in vivo (1970-2026): dal condrocita autologo a cellule mesenchimali, iPSC e supporti a gradiente; nessun esito quantificato nell'abstract.",ax:"Zelinka, Roelofs, Kandel, De Bari",date:"set 2026",meta:"rassegna narrativa con ricerca su PubMed e ClinicalTrials.gov · [V]",pmid:'42810572',doi:'10.1016/j.joca.2026.09.016',journal:"Osteoarthritis and cartilage",authors:"Zelinka AA, Roelofs AJ, Kandel RA, De Bari C",design:"Rassegna narrativa: pubblicazioni dal 1970 al 2026 individuate su PubMed, concentrate su interventi cellulari e di ingegneria tissutale valutati in vivo; studi clinici da ClinicalTrials.gov.",pop:"Non applicabile: nessun numero di studi o pazienti riportato nell'abstract.",results:"Nessun risultato quantificato nell'abstract. Descrive l'impianto di condrociti autologhi come tecnica pionieristica e le strategie successive (condrociti coltivati, cellule stromali mesenchimali, cellule staminali pluripotenti indotte, supporti sempre più sofisticati con disegni a gradiente). Dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori concludono che le terapie rigenerative hanno un potenziale di beneficio duraturo, ma tradurle in clinica resta la sfida: una soluzione unica è irrealistica, e identificare i pazienti che rispondono a un trattamento specifico ne aumenterà il successo; nell'articolazione artrosica la riparazione può richiedere strategie più complesse.",limits:"Rassegna narrativa: non dice come sono stati scelti e pesati gli studi, e non consente di confrontare le tecniche · nessun esito clinico quantificato nell'abstract · articolo non open access: testo completo non aperto.",perte:"Fa da mappa del campo in cui operi con AMIC e minced cartilage: l'abstract non nomina Chondro-Gide né AutoCart, quindi non dice nulla di specifico sulla tua filiera. Utile come cornice per T4, non come dato."},{n:7,mono:"m-gray",dot:"gray",sec:"res",j:"Osteoarthritis and Cartilage",h:"TC in carico: il C-score del femore si associa alla progressione dell'artrosi",v:"Coorte MOST, 649 ginocchia: C-score basale associato a peggioramento dello spazio articolare mediale (OR 1,43; IC 95% 1,07-1,92) e del dolore a 2 anni (OR 1,27; IC 95% 1,00-1,62); associazioni moderate.",ax:"Li, Segal, Tolstykh, Nevitt, Turmezei",date:"set 2026",meta:"coorte prospettica (Multicenter Osteoarthritis Study), 649 ginocchia, 2 anni · [III]",pmid:'42810573',doi:'10.1016/j.joca.2026.09.015',journal:"Osteoarthritis and cartilage",authors:"Li S, Segal NA, Tolstykh I, Nevitt MC, Turmezei TD",design:"Analisi nella Multicenter Osteoarthritis Study di un nuovo indice, il «C-score», derivato dalla forma del femore distale su TC in carico con modelli statistici di forma: distanza lungo il vettore di forma fra le forme medie KL0/1 e KL2/3, standardizzata a 1 DS di KL0/1. Associazione con il peggioramento a 2 anni del grado OARSI di restringimento dello spazio articolare mediale e con il peggioramento minimo clinicamente importante del dolore (2 punti WOMAC dolore); equazioni di stima generalizzate aggiustate per sesso, età, BMI e più ginocchia per partecipante.",pop:"649 ginocchia (56,3% donne, età media 63,8 anni, DS 9,6; BMI 28,5 kg/m², DS 5,0), con o a rischio di artrosi sintomatica del ginocchio; 70 ginocchia con peggioramento dello spazio articolare mediale.",results:"C-score basale associato alla progressione del restringimento dello spazio articolare (OR 1,43; IC 95% 1,07-1,92; p=0,01) e al peggioramento clinicamente importante del dolore a 2 anni (OR 1,27; IC 95% 1,00-1,62; p=0,047). Le differenze fra i sessi (associazione con lo spazio più marcata negli uomini, con il dolore nelle donne) non sono significative (p>0,05).",concl:"Gli autori concludono che C-score più alti sono moderatamente associati alla progressione del restringimento mediale e al peggioramento del dolore a 2 anni, e che il C-score è un promettente biomarcatore di imaging.",limits:"Solo 70 ginocchia con progressione: stime imprecise · l'associazione con il dolore è al limite (IC 95% 1,00-1,62; p=0,047) · misura di ricerca, senza soglia decisionale né validazione su altre coorti nell'abstract · articolo non open access: testo completo non aperto.",perte:"Non cambia nulla nella tua pratica oggi: è un biomarcatore di ricerca su TC in carico, nessuna indicazione per osteotomia o protesi. Segnalato perché riguarda la stima del rischio di progressione dell'artrosi."},{n:8,mono:"m-gray",dot:"gray",sec:"res",j:"The Journal of Knee Surgery",h:"Protesi di ginocchio: un nomogramma prevede il recupero scarso a 3 mesi",v:"Coorte retrospettiva di 360 protesi: nomogramma con 6 predittori, incluso il liquido sinoviale; AUC 0,861 (IC 95% 0,782-0,934) nel test interno, 0,842 corretta per ottimismo; modello in sviluppo, senza validazione esterna.",ax:"Li, Hong, Gong, Deng, Huang, Wang",date:"set 2026",meta:"coorte retrospettiva, 360 protesi totali primarie, modello prognostico con validazione interna · [IV]",pmid:'42810402',doi:'10.1055/a-2968-5875',journal:"The journal of knee surgery",authors:"Li J, Hong Z, Gong Z, Deng H, Huang Z, Wang J",design:"Sviluppo e valutazione interna di un nomogramma multidimensionale che integra il danno cartilagineo intraoperatorio (grado di Outerbridge) e biomarcatori del liquido sinoviale perioperatorio (IL-6, TNF-α, COMP, BDNF totale, prelevati dopo l'induzione dell'anestesia e prima dell'incisione) con variabili cliniche. Esito: recupero funzionale a 3 mesi, definito con la sottoscala funzione del WOMAC. Selezione dei predittori con LASSO, regressione logistica multivariata, valutazione con AUC, calibrazione e analisi decisionale.",pop:"360 pazienti sottoposti a protesi totale di ginocchio primaria monolaterale.",results:"Sei predittori nel modello finale: età, BMI, WOMAC funzione preoperatorio, grado di Outerbridge, log(IL-6) e log(COMP). AUC 0,861 (IC 95% 0,782-0,934) nel gruppo di test interno; calibrazione accettabile (Hosmer-Lemeshow p=0,45); AUC corretta per ottimismo con bootstrap 0,842. L'analisi decisionale suggerisce un possibile beneficio netto nelle soglie valutate.",concl:"Gli autori concludono che il nomogramma stima la probabilità di scarso recupero funzionale a 3 mesi, ma va considerato un modello perioperatorio in fase di sviluppo che richiede validazione prospettica esterna prima di qualunque uso clinico.",limits:"Validazione solo interna, sullo stesso centro e sugli stessi dati: la prestazione su altri ospedali è sconosciuta · richiede un prelievo di liquido sinoviale prima dell'incisione, non routinario · l'abstract non dice quale soglia di WOMAC definisca il recupero «scarso» né quanti pazienti l'abbiano · articolo non open access: testo completo non aperto.",perte:"Non è una tecnica tua ma un modello per la protesi totale: prevede il recupero a 3 mesi, non l'esito a lungo termine, e non è utilizzabile oggi. Riguarda i pazienti protesizzati, anche con VELYS, senza dati specifici sulla piattaforma."}];
var SUGGQ=[{k:"kol",n:"Michael T. Hirschmann",w:"Kantonsspital Baselland (Bruderholz), Svizzera — coautore dello studio di oggi sull'allineamento cinematico contro meccanico nella protesi totale (KSSTA, PMID 42809367); corrispondenza tecnica con la tua protesi totale con robot VELYS, dove l'obiettivo di allineamento è un tema discusso. Sostituisce Thomas Neri (29 settembre, nessun segnale dell'utente arrivato per farlo ruotare)."}];
var BRIEF_TEXT="Il lavoro del giorno riguarda la tua tecnica sulla radice meniscale. Una revisione sistematica pubblicata su Arthroscopy, dodici studi fra clinici e biomeccanici, confronta la sutura all-inside della radice posteriore del menisco mediale con il pull-out transtibiale, che è la tecnica che usi. Nei quattro studi clinici con confronto diretto, centocinquantatré pazienti in tutto, entrambe le tecniche migliorano i punteggi riferiti dal paziente e nessuna prevale in modo costante: la guarigione completa va dal sessantaquattro al sessantotto per cento con l'all-inside e dal ventuno all'ottantasei per cento con il pull-out, intervalli troppo larghi per un verdetto. Il dato che pesa è un altro: nessuna delle due tecniche corregge in modo costante l'estrusione del menisco, il punto su cui insiste la tensione sulla radice. Gli autori indicano la centralizzazione come aggiunta possibile, ma la revisione non l'ha verificata; gli studi sono in gran parte non randomizzati e molto eterogenei.\n\nSeconda scheda: un consensus Delphi di ventinove esperti, con Robert LaPrade fra gli autori, sul tutore di scarico nell'artrosi tibiofemorale. Il panel sostiene il tutore come prova di selezione prima di un'osteotomia, una prova diagnostica di almeno sei settimane e un periodo terapeutico di sei mesi; è un accordo di esperti, non un dato di efficacia. Sul legamento femoro-rotuleo mediale, uno studio retrospettivo su ottantaquattro ginocchia confronta due fissazioni femorali, sling dell'adduttore e tunnel anatomico, senza una differenza chiara sul punteggio di Kujala: con soli diciotto ginocchi nel braccio sling, il silenzio è largo, e nessuno dei due bracci coincide con la tua fissazione con ancore.\n\nLe altre schede: una coorte retrospettiva di seicentoventidue protesi totali associa l'allineamento cinematico a meno sintomi residui a un anno rispetto al meccanico, ma non è randomizzata; uno studio su settantaquattro revisioni suggerisce che i controlli programmati a distanza scoprono di rado un problema, ma include solo pazienti già rivisti; una rassegna sulla riparazione della cartilagine conclude che una soluzione unica per tutti è irrealistica; un biomarcatore su tomografia in carico, il C-score, si associa moderatamente alla progressione dell'artrosi; e un nomogramma per il recupero a tre mesi dopo protesi è ancora in sviluppo, senza validazione esterna.\n\nNessun richiamo nuovo: i richiami del nucleo sorvegliato restano quelli già noti. Nessuna ritrattazione nuova sul citato. Nessuna voce nuova fra le linee guida degli ultimi sessanta giorni. Oggi si è mossa la tensione sulla radice meniscale: nessuna delle due suture corregge l'estrusione.";
var BRIEF_DIALOGO=[{"chi": "A", "t": "Il lavoro di oggi tocca la tua tecnica sulla radice meniscale: una revisione sistematica su Arthroscopy, dodici studi, che confronta la sutura all-inside con il pull-out transtibiale."}, {"chi": "B", "t": "Quindi con il tuo pull-out come uno dei due bracci. Che cosa emerge?"}, {"chi": "A", "t": "Nei quattro studi clinici con confronto diretto, centocinquantatré pazienti in tutto, entrambe le tecniche migliorano i punteggi riferiti dal paziente e nessuna prevale in modo costante."}, {"chi": "B", "t": "Ma sulla guarigione ci sono differenze?"}, {"chi": "A", "t": "La guarigione completa va dal sessantaquattro al sessantotto per cento con l'all-inside e dal ventuno all'ottantasei per cento con il pull-out. Intervalli così larghi non permettono un verdetto."}, {"chi": "B", "t": "E il punto della tensione, l'estrusione?"}, {"chi": "A", "t": "Ecco il dato che pesa: nessuna delle due tecniche corregge in modo costante l'estrusione del menisco. Gli autori indicano la centralizzazione come aggiunta possibile, ma la revisione non l'ha verificata."}, {"chi": "B", "t": "Quindi per te la tensione sulla radice si muove, ma non si chiude."}, {"chi": "A", "t": "Esatto. Gli studi sono in gran parte non randomizzati e molto eterogenei: serve ancora il trial sulla centralizzazione. Poi c'è un consensus Delphi di ventinove esperti, con LaPrade, sul tutore di scarico nell'artrosi."}, {"chi": "B", "t": "Che cosa dice, per la tua chirurgia correttiva?"}, {"chi": "A", "t": "Sostiene il tutore come prova prima di un'osteotomia: almeno sei settimane per la prova diagnostica, sei mesi per quella terapeutica. È un accordo di esperti, non un dato di efficacia."}, {"chi": "B", "t": "E il legamento femoro-rotuleo mediale?"}, {"chi": "A", "t": "Uno studio su ottantaquattro ginocchia confronta il sling dell'adduttore con il tunnel anatomico: nessuna differenza chiara sul Kujala, ma con diciotto ginocchi nel braccio sling il silenzio è largo. E nessuno dei due coincide con la tua fissazione."}, {"chi": "B", "t": "Richiami e ritrattazioni?"}, {"chi": "A", "t": "Nessun richiamo nuovo, nessuna ritrattazione nuova sul citato, e nessuna linea guida nuova oltre al consensus di oggi."}];
